package org.quietreader.data

import android.test.AndroidTestCase
import com.google.gson.*
import org.quietreader.core.*
import org.quietreader.poetry.*

@Suppress("DEPRECATION")
class PoemStoreTest:AndroidTestCase(){
    private lateinit var library:LibraryStore
    private lateinit var poems:PoemStore
    private val db="poetry-instrumentation.db"
    override fun setUp(){super.setUp();context.deleteDatabase(db);library=LibraryStore(context,db);poems=PoemStore(library)}
    private fun importExample():PoemStore.Entry{val document=Protocol.parse(javaClass.classLoader!!.getResourceAsStream("protocol/poetry-example.json")!!.bufferedReader().use{it.readText()},"fixture").document!!;library.importFile(document);return poems.entries().first()}
    fun testFreshDatabaseIsEmpty(){assertTrue(poems.entries().isEmpty());assertTrue(library.listBooks().isEmpty())}
    fun testOverlayAndDraftSurviveBackupAndReopen(){val e=importExample();val changed=e.poem.deepCopy().apply{addProperty("title","编辑后的诗")};poems.save("draft:${e.key}",JsonObject().apply{add("poem",changed);addProperty("base",Poetry.revision(e.poem))});poems.saveEdit(e,changed,Poetry.revision(e.poem));assertEquals("编辑后的诗",poems.entry(e.key)!!.poem.s("title"));assertEquals(e.poem.s("title"),library.section(e.book,e.id)!!.s("title"));val snapshot=library.backup();assertTrue(library.validateBackup(snapshot).isEmpty());library.restoreBackup(snapshot);library.close();library=LibraryStore(context,db);poems=PoemStore(library);assertEquals("编辑后的诗",poems.entry(e.key)!!.poem.s("title"))}
    fun testStaleDraftCannotOverwriteNewRevision(){val e=importExample();val old=Poetry.revision(e.poem);poems.saveEdit(e,e.poem.deepCopy().apply{addProperty("title","版本二")},old);var rejected=false;try{poems.saveEdit(e,e.poem.deepCopy().apply{addProperty("title","过期草稿")},old)}catch(_:IllegalArgumentException){rejected=true};assertTrue(rejected);assertEquals("版本二",poems.entry(e.key)!!.poem.s("title"))}
    fun testCollectionDeletionKeepsPoemEntity(){val e=importExample();val group=JsonObject().apply{addProperty("id","group");addProperty("name","练习");add("members",JsonArray().apply{add(e.key)})};poems.saveCollections(JsonArray().apply{add(group)});poems.saveCollections(JsonArray());assertNotNull(poems.entry(e.key));assertTrue(poems.collections().isEmpty())}
    fun testSelectedBackupRemovesOtherBooksDraftsAndQuestionSnapshots(){val e=importExample();val other=library.book(e.book)!!.deepCopy().apply{addProperty("id","other-book")};library.importFile(Protocol.wrap(listOf(other)));val second=poems.entries().first{it.book=="other-book"};poems.save("draft:${second.key}",JsonObject().apply{addProperty("secret","other-secret")});poems.save("session",JsonObject());LearnActivity.create(poems,Poetry.questions(listOf(Poetry.Candidate(e.key,e.poem),Poetry.Candidate(second.key,second.poem)),"整篇",2,1,"诗文不重复"),"抽背");val backup=library.selectedBackup(listOf(e.book));assertFalse(backup.toString().contains("other-secret"));val metadata=backup.getAsJsonObject("metadata");val session=JsonParser.parseString(metadata.get("remote:poetry:session").asString).asJsonObject;assertEquals(1,session.getAsJsonArray("questions").size());assertEquals(e.key,session.getAsJsonArray("questions")[0].asJsonObject.s("key"))}
    fun testRemoteUpdatesKeepLocalOverlay(){val e=importExample();val book=library.book(e.book)!!;val source=JsonObject().apply{addProperty("identity","1/lib/book");addProperty("repositoryId","1");addProperty("revision","first")};val id=library.importRemote(book,source);val remote=poems.entries().first{it.book==id};poems.saveEdit(remote,remote.poem.deepCopy().apply{addProperty("title","我的版本")},Poetry.revision(remote.poem));val changed=book.deepCopy();changed.getAsJsonArray("poems")[0].asJsonObject.addProperty("title","来源新版");library.importRemote(changed,source.apply{addProperty("revision","second")});assertEquals("我的版本",poems.entry(remote.key)!!.poem.s("title"));assertEquals("来源新版",poems.entry(remote.key)!!.source.s("title"))}
    fun testLearningCheckpointAndHistoryUseSeparateSnapshots(){val e=importExample();LearnActivity.create(poems,Poetry.questions(listOf(Poetry.Candidate(e.key,e.poem)),"随机句",2,1,"题目不重复"),"抽背");val session=poems.state("session");val id=session.s("id");LearnActivity.create(poems,Poetry.questions(listOf(Poetry.Candidate(e.key,e.poem)),"整篇",1,1,"允许重复"),"抽背");assertEquals(id,poems.state("session").s("id"));val original=session.getAsJsonArray("questions")[0].asJsonObject.getAsJsonObject("poem").s("title");poems.saveEdit(e,e.poem.deepCopy().apply{addProperty("title","修改正文")},Poetry.revision(e.poem));assertEquals(original,poems.state("session").getAsJsonArray("questions")[0].asJsonObject.getAsJsonObject("poem").s("title"))}
    override fun tearDown(){library.close();context.deleteDatabase(db);super.tearDown()}
}
